const lessons=[{"sentences":[{"speaker":"A","text":"Welcome everyone to our final planning meeting for the upcoming neighbourhood spring festival.","position":1,"audioStartSeconds":0,"audioEndSeconds":5.623541666666667},{"speaker":"A","text":"Before we open the gates on Saturday morning, I need to share some essential practical details with you all.","position":2,"audioStartSeconds":5.823541666666666,"audioEndSeconds":12.241875},{"speaker":"A","text":"Let us start with the main entrance gate which opens at nine in the morning for early visitors.","position":3,"audioStartSeconds":12.441875,"audioEndSeconds":18.150625},{"speaker":"A","text":"Parking spaces are very limited this year because the west field is currently being repaired by the council.","position":4,"audioStartSeconds":18.350625,"audioEndSeconds":24.742375},{"speaker":"A","text":"Therefore, we strongly advise every attendee to use public buses or arrive on bicycles if possible.","position":5,"audioStartSeconds":24.942375,"audioEndSeconds":31.707833333333333},{"speaker":"A","text":"If you drive a vehicle, you must leave it in the south car park near the library.","position":6,"audioStartSeconds":31.907833333333333,"audioEndSeconds":36.817625},{"speaker":"A","text":"Moving on to ticket prices, general admission remains completely free for children and senior citizens.","position":7,"audioStartSeconds":37.017625,"audioEndSeconds":43.757333333333335},{"speaker":"A","text":"Adult tickets cost ten pounds each when purchased online or twelve pounds at the entrance.","position":8,"audioStartSeconds":43.95733333333333,"audioEndSeconds":49.678958333333334},{"speaker":"A","text":"Please remember that all cash payments should be handed to the main finance desk inside the tent.","position":9,"audioStartSeconds":49.87895833333334,"audioEndSeconds":55.651},{"speaker":"A","text":"Regarding our schedule, there is one important programme change you should note down right now.","position":10,"audioStartSeconds":55.851,"audioEndSeconds":61.31608333333333},{"speaker":"A","text":"The traditional dancing show was originally scheduled for noon on the central wooden stage.","position":11,"audioStartSeconds":61.516083333333334,"audioEndSeconds":67.16041666666666},{"speaker":"A","text":"However, the dance troupe leader called us this morning to report a sudden illness among performers.","position":12,"audioStartSeconds":67.36041666666667,"audioEndSeconds":73.43},{"speaker":"A","text":"Consequently, we have moved the dancing performance to the afternoon slot starting at three.","position":13,"audioStartSeconds":73.63,"audioEndSeconds":79.313},{"speaker":"A","text":"In its original morning slot, we will instead host a local acoustic guitar concert for visitors.","position":14,"audioStartSeconds":79.513,"audioEndSeconds":85.73720833333333},{"speaker":"A","text":"Food stalls will operate throughout the day offering hot meals and refreshing cold drinks.","position":15,"audioStartSeconds":85.93720833333333,"audioEndSeconds":91.517125},{"speaker":"A","text":"Volunteers should report to the information booth wearing their bright yellow vests by eight.","position":16,"audioStartSeconds":91.717125,"audioEndSeconds":97.30229166666666}],"questions":[{"prompt":"Main entrance opening time: ______","answer":"nine","evidenceSentence":3,"evidence":"nine in the morning","explanation":"Người nói cho biết cổng chính mở cửa vào lúc chín giờ sáng (nine)."},{"prompt":"Alternative parking location: ______ car park","answer":"south","evidenceSentence":6,"evidence":"south car park","explanation":"Người tham dự được hướng dẫn đỗ xe ở bãi đỗ xe phía nam (south)."},{"prompt":"Adult ticket price online: ______ pounds","answer":"ten","evidenceSentence":8,"evidence":"ten pounds each","explanation":"Vé người lớn mua trực tuyến có giá mười bảng (ten)."},{"prompt":"Payment collection location: finance ______","answer":"desk","evidenceSentence":9,"evidence":"finance desk","explanation":"Tiền mặt cần được nộp tại bàn tài chính (desk) bên trong lều."},{"prompt":"Rescheduled dancing start time: ______","answer":"three","evidenceSentence":13,"evidence":"starting at three","explanation":"Buổi biểu diễn múa đã được chuyển sang buổi chiều bắt đầu lúc ba giờ (three)."},{"prompt":"Volunteer vest colour: ______","answer":"yellow","evidenceSentence":16,"evidence":"yellow vests","explanation":"Tình nguyện viên cần mặc áo lê-ghê màu vàng (yellow) của họ."}]}];const cards=[...document.querySelectorAll('article')];let stopping=null,stoppingAudio=null;
    document.addEventListener('play',event=>{if(event.target.tagName!=='AUDIO')return;document.querySelectorAll('audio').forEach(a=>{if(a!==event.target)a.pause()})},true);
    document.querySelectorAll('[data-filter]').forEach(button=>button.onclick=()=>{let count=0;cards.forEach(c=>{c.hidden=button.dataset.filter!=='ALL'&&c.dataset.goal!==button.dataset.filter;if(!c.hidden)count++;else c.querySelector('audio').pause()});document.querySelectorAll('[data-filter]').forEach(b=>b.setAttribute('aria-pressed',b===button));document.querySelector('#filter-status').textContent='Đang hiển thị '+count+' bài.'});
    const normal=value=>value.trim().toLowerCase().replace(/\s+/g,' ');
    document.querySelectorAll('[data-check]').forEach(button=>button.onclick=()=>{const i=Number(button.dataset.check);let score=0;lessons[i].questions.forEach((q,n)=>{const value=normal(document.getElementById('answer-'+i+'-'+n).value);if([q.answer,...(q.accepted||[])].some(a=>normal(a)===value))score++});document.getElementById('result-'+i).textContent=score+'/'+lessons[i].questions.length+' câu đúng. Mở phần đáp án để xem giải thích.'});
    document.querySelectorAll('[data-segment]').forEach(button=>button.onclick=async()=>{if(stopping)stopping();const [i,n]=button.dataset.segment.split(',').map(Number),audio=cards[i].querySelector('audio'),s=lessons[i].sentences[n];audio.currentTime=s.audioStartSeconds;const stop=()=>{stopping=null;stoppingAudio=null;audio.removeEventListener('timeupdate',check);audio.pause()},check=()=>{if(audio.currentTime>=s.audioEndSeconds)stop()};stopping=stop;stoppingAudio=audio;audio.addEventListener('timeupdate',check);try{await audio.play()}catch(_){stop();document.getElementById('result-'+i).textContent='Không phát được audio. Hãy dùng nút tải WAV để nghe.'}});
    document.querySelectorAll('audio').forEach(audio=>audio.addEventListener('pause',()=>{if(audio.paused&&stoppingAudio===audio&&stopping)stopping()}));
const authStatus=document.querySelector('#auth-status');
async function initializeAudio(){
 try{
  const response=await fetch('/api/auth/me',{credentials:'same-origin'});
  if(response.status===401){authStatus.hidden=false;authStatus.innerHTML='Đăng nhập để nghe audio. <a href="/login?next=%2Fcatalog%3Fgoal%3DALL">Đăng nhập</a> rồi mở bài từ thư viện bằng nút “Nghe toàn bài & làm câu hỏi”.';return}
  if(!response.ok)throw Error('account');
  document.querySelectorAll('audio').forEach(audio=>{audio.src=audio.dataset.src;audio.preload='none';audio.hidden=false});
  document.querySelectorAll('[data-segment]').forEach(button=>button.disabled=false);
  document.querySelectorAll('a[download]').forEach(link=>link.hidden=false);
 }catch(_){authStatus.hidden=false;authStatus.textContent='Không kiểm tra được đăng nhập. Hãy tải lại trang để thử lại.'}
}
initializeAudio();
